using Marketplace.Domain.Common; namespace Marketplace.Domain.Inventory; public sealed class InventoryReservation:AggregateRoot<long>{private InventoryReservation(){}public long OrderId{get;private set;}public long ProductId{get;private set;}public long ProductVariantId{get;private set;}public int Quantity{get;private set;}public InventoryReservationStatus Status{get;private set;}public DateTime ReservedAtUtc{get;private set;}public DateTime ExpiresAtUtc{get;private set;}public DateTime? CompletedAtUtc{get;private set;}public static InventoryReservation Create(long id,long orderId,long productId,long variantId,int qty,DateTime expires){if(qty<=0||expires<=DateTime.UtcNow)throw new DomainException("Invalid inventory reservation.");return new(){Id=id,OrderId=orderId,ProductId=productId,ProductVariantId=variantId,Quantity=qty,Status=InventoryReservationStatus.Reserved,ReservedAtUtc=DateTime.UtcNow,ExpiresAtUtc=expires};}public void Consume(){Require();Status=InventoryReservationStatus.Consumed;CompletedAtUtc=DateTime.UtcNow;}public void Release(){Require();Status=InventoryReservationStatus.Released;CompletedAtUtc=DateTime.UtcNow;}public void Expire(){Require();Status=InventoryReservationStatus.Expired;CompletedAtUtc=DateTime.UtcNow;}private void Require(){if(Status!=InventoryReservationStatus.Reserved)throw new DomainException("Reservation is not active.");}}
